DROP TABLE IF EXISTS `branches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `branches` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `address` varchar(255) NOT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `color` varchar(255) NOT NULL,
  `moodnote_color_1` varchar(10) DEFAULT '#f5c6d0',
  `moodnote_color_2` varchar(10) DEFAULT '#3b5998',
  `status` enum('active','trash') NOT NULL,
  `created_by` int(11) NOT NULL,
  `updated_by` int(11) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `bus_change_logo` varchar(255) DEFAULT NULL,
  `serving_kitchen` int(11) DEFAULT NULL,
  `letterhead_image` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT '',
  `friendly_name` varchar(255) DEFAULT NULL,
  `neighborhood` varchar(100) DEFAULT NULL,
  `neighborhood_id` int(11) DEFAULT NULL,
  `facility_name_for_ddi` varchar(255) DEFAULT NULL,
  `nap_time` tinyint(1) DEFAULT 0,
  `closing_time` time DEFAULT NULL COMMENT 'When this branch closes. NULL means use the site-wide closing_time setting, including for branches created later.',
  `dc_number` int(5) DEFAULT 0,
  `phone` varchar(50) DEFAULT NULL,
  `immunization_contact_id` int(11) DEFAULT NULL,
  `enrollment_contact_id` int(11) DEFAULT NULL,
  `secretary_contact_id` int(11) DEFAULT NULL,
  `director_contact_id` int(11) DEFAULT NULL,
  `transportation_contact_id` int(11) DEFAULT NULL,
  `has_transportation` tinyint(1) NOT NULL DEFAULT 1,
  `header_text` varchar(255) DEFAULT NULL,
  `header_color` varchar(10) DEFAULT '#2c3e50',
  `footer_text` varchar(255) DEFAULT NULL,
  `footer_color` varchar(10) DEFAULT '#34495e',
  `hebrew_name` varchar(255) DEFAULT NULL,
  `company_name` varchar(255) DEFAULT NULL,
  `ein` varchar(20) DEFAULT NULL COMMENT 'This branch legal entity EIN, digits and hyphen. NULL/empty means this branch prints no EIN. Never inherited from the organization: see the migration header.',
  `show_ein_on_pdf` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Print the EIN on this branch payment PDFs. 0 hides it. Ships off so existing statements are unchanged.',
  `entry_card_file` varchar(255) DEFAULT NULL,
  `entry_card_color` varchar(20) DEFAULT NULL,
  `entry_card_secondary_color` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `status` (`status`),
  KEY `name` (`name`),
  KEY `fk_serving_kitchen` (`serving_kitchen`),
  KEY `idx_branches_imm_contact` (`immunization_contact_id`),
  KEY `idx_branches_enr_contact` (`enrollment_contact_id`),
  KEY `idx_branches_sec_contact` (`secretary_contact_id`),
  KEY `idx_branches_dir_contact` (`director_contact_id`),
  KEY `idx_branches_trans_contact` (`transportation_contact_id`),
  KEY `idx_neighborhood_id` (`neighborhood_id`),
  CONSTRAINT `fk_serving_kitchen` FOREIGN KEY (`serving_kitchen`) REFERENCES `kitchens` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
