  `polyline` mediumtext NOT NULL COMMENT 'JSON [[lat,lng],...] simplified representative path',
  `length_m` int(11) NOT NULL DEFAULT 0,
  `stop_offsets` mediumtext DEFAULT NULL COMMENT 'JSON [{child_id, offset_m, dist_m}] meters along the path per roster stop',
  `segment_minutes` mediumtext DEFAULT NULL COMMENT 'JSON [{from_m, to_m, minutes}] coarse measured drive times',
  `source` enum('geotab','tablet') NOT NULL DEFAULT 'geotab',
