  `snapped` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = geometry road-snapped via OSRM /match',
  `confidence` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0-100 from days_used + agreement',
  `window_from` date DEFAULT NULL,
  `window_to` date DEFAULT NULL,
  `built_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_route` (`bus_route_id`)
