CREATE TABLE `child_charges` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `child_id` int(11) NOT NULL,
  `charge_type_id` int(11) DEFAULT NULL,
  `charge_kind` enum('monthly','one_time') NOT NULL DEFAULT 'monthly' COMMENT 'monthly = recurs every month from charge_start_date, forever. one_time = charged once, in the month of charge_start_date, with monthly_cost as the amount. Ships as monthly so existing rows are unchanged.',
  `name` varchar(100) NOT NULL COMMENT 'e.g. Transportation, Clothing, Trip Fee',
  `monthly_cost` decimal(10,2) NOT NULL DEFAULT 0.00,
  `yearly_cost` decimal(10,2) NOT NULL DEFAULT 0.00,
  `charge_start_date` date DEFAULT NULL,
  `payment_method_id` int(11) DEFAULT NULL,
  `status` enum('active','trash') NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `one_time_uniq` varchar(200) GENERATED ALWAYS AS (case when `charge_kind` = 'one_time' and `status` = 'active' then concat(`child_id`,'|',`charge_start_date`,'|',lcase(trim(`name`))) else NULL end) VIRTUAL COMMENT 'Derived identity of an ACTIVE one-time charge (child|month|name), NULL for every other row so they are exempt from the unique key below. Do not write to this column.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_child_charges_one_time` (`one_time_uniq`),
  KEY `idx_child_id` (`child_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1076 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
