DROP TABLE IF EXISTS `sms_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `sms_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `phone` varchar(50) DEFAULT NULL COMMENT 'destination. NULL when the message was suppressed because there was no number we were permitted to use',
  `message` text NOT NULL,
  `type` varchar(32) NOT NULL DEFAULT 'alerts',
  `lane` varchar(16) NOT NULL DEFAULT 'staff',
  `channel` enum('sms','voice') NOT NULL DEFAULT 'sms' COMMENT 'voice rows come from sendTwilioVoice, which logged nothing at all before this',
  `direction` enum('out','in') NOT NULL DEFAULT 'out' COMMENT 'inbound rows let one table hold both halves of a conversation',
  `audience` enum('staff','family','unknown') NOT NULL DEFAULT 'unknown' COMMENT 'who this was for. Recorded at send time by the caller, NEVER inferred later from current contact records: numbers get recycled and a staff member can also be a parent, so a read-time lookup would silently move old rows between tabs',
  `audience_source` enum('original','backfill','unknown') NOT NULL DEFAULT 'unknown' COMMENT 'how we know the audience. Rows that predate the fix stay honest as unknown rather than being guessed at',
  `segments` int(11) NOT NULL DEFAULT 1,
  `event_uuid` char(36) DEFAULT NULL COMMENT 'our own id, minted BEFORE the Twilio call and carried in the statusCallback URL. Routes a receipt to the right tenant and the right row even when the API call timed out and we never learned the SID',
  `twilio_sid` varchar(64) DEFAULT NULL COMMENT 'MessageSid or CallSid, once Twilio gives us one',
  `status` enum('success','failed','blocked','suppressed','received','pending','unknown') NOT NULL,
  `provider_status` varchar(32) DEFAULT NULL COMMENT 'Twilio''s own word, verbatim: queued/sending/sent/delivered/undelivered/failed, or initiated/ringing/answered/completed/busy/no-answer/canceled for voice. NULL means no receipt has ever arrived, which is true of every row predating this migration',
  `provider_status_at` datetime DEFAULT NULL COMMENT 'when the last receipt landed, so a late out-of-order one can be ignored rather than regressing the state',
  `suppression_reason_code` varchar(32) DEFAULT NULL COMMENT 'OUR policy decision: no_textable_number, recipient_rate_limit, tenant_quota, child_parked, blast_limit, staff_cap, opted_out, muted',
  `provider_error_code` varchar(16) DEFAULT NULL COMMENT 'TWILIO''s error code: 30003 unreachable, 30006 landline, 30007 carrier filtered, 21610 unsubscribed. Kept in its own namespace so a carrier code can never collide with one of ours',
  `error` varchar(255) DEFAULT NULL COMMENT 'diagnostic detail for a human. Never the key anything branches on',
  `recipient_id` int(11) DEFAULT NULL COMMENT 'the contact or admin we meant to reach. The only identity a suppressed row has, since it has no phone',
  `recipient_label` varchar(120) DEFAULT NULL COMMENT 'their name as it was AT THE TIME. A snapshot, so the log still reads correctly after a rename or a deletion',
  `alert_id` int(11) DEFAULT NULL COMMENT 'the alerts.id this was raised from, so a log row links back to the board',
  `batch_id` char(36) DEFAULT NULL COMMENT 'shared by every row of one bulk send. A notice to 100 families is 100 rows, because each gets its own SID and its own outcome',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sms_sid` (`twilio_sid`),
  UNIQUE KEY `uq_sms_event` (`event_uuid`),
  KEY `idx_sms_lane_created` (`lane`,`created_at`),
  KEY `idx_sms_phone_created` (`phone`,`created_at`),
  KEY `idx_sms_retention` (`created_at`,`id`),
  KEY `idx_sms_audience_created` (`audience`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=23403 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
